import React from 'react';
import { Text, View, TouchableOpacity } from 'react-native';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';
import { AntDesign } from '@expo/vector-icons';
import { Ionicons } from '@expo/vector-icons';
import { styles } from './styles';

export function ListFooter() {
    const { listData, perPage, isMountedApi } = useContexState();
    const { LoadPage } = useLoadPage();

    function load() {
        return LoadPage(Number(listData[perPage - 1]?.firstCard + 6));
    };

    return (<>
        {listData[perPage - 1]?.firstCard < 9999 && isMountedApi ?
            <View style={styles.containerButton}>
                <TouchableOpacity onPress={load}>
                    <AntDesign
                        name="caretdown"
                        style={styles.button}
                        size={24}
                        color="rgb(200,200,200)" />
                </TouchableOpacity>
            </View> : null}
        <Text style={{ fontSize: 15, color: '#fff', textAlign: 'center'}}> Construído com {
            <AntDesign name="heart" size={15} color='#FF0000' />
        } e {<Ionicons name="cafe" size={17} color="#FFC222" />} por {<Text style={{textDecorationLine: 'underline'}}>Fabio Moraes</Text>}.</Text>
    </>

    );
};
